package ro.leo.visual;
import ro.leo.i18n.L;import android.app.*;import android.content.*;import android.media.*;import android.os.*;
/** One precomputed PCM bar loops in AudioTrack; no UI timer drives the sound. */
public final class MetronomeService extends Service implements AudioManager.OnAudioFocusChangeListener {
 static MetronomeService instance;static int bpm=100,beats=4;private AudioTrack track;private AudioManager audio;private int beatSamples;
 static short[] bar(int bpm,int beats){if(bpm<30||bpm>240||beats<1||beats>8)throw new IllegalArgumentException();int period=(int)Math.round(22050.0*60/bpm);short[] pcm=new short[period*beats];for(int beat=0;beat<beats;beat++)for(int n=0;n<441;n++)pcm[beat*period+n]=(short)(Math.sin(2*Math.PI*(beat==0?1400:900)*n/22050)*5000*(1-n/441.0));return pcm;}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();instance=this;audio=(AudioManager)getSystemService(AUDIO_SERVICE);}
 public int onStartCommand(Intent i,int flags,int id){if(i==null||"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel("leo-metronome",L.t("Metronom"),NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);nm.createNotificationChannel(channel);PendingIntent stop=PendingIntent.getService(this,460,new Intent(this,MetronomeService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent open=PendingIntent.getActivity(this,460,new Intent(this,MetronomeActivity.class),PendingIntent.FLAG_UPDATE_CURRENT);startForeground(460,new Notification.Builder(this,"leo-metronome").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(L.t("Metronom")).setContentText("BPM · "+i.getIntExtra("bpm",100)).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,L.t("Oprește"),stop).build()).build());try{if(((android.telecom.TelecomManager)getSystemService(TELECOM_SERVICE)).isInCall()||audio.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){stopSelf();return START_NOT_STICKY;}int nextBpm=i.getIntExtra("bpm",100),nextBeats=i.getIntExtra("beats",4);short[] pcm=bar(nextBpm,nextBeats);release();bpm=nextBpm;beats=nextBeats;beatSamples=pcm.length/beats;track=new AudioTrack(AudioManager.STREAM_MUSIC,22050,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,pcm.length*2,AudioTrack.MODE_STATIC);if(track.getState()!=AudioTrack.STATE_INITIALIZED||track.write(pcm,0,pcm.length)!=pcm.length||track.setLoopPoints(0,pcm.length,-1)!=AudioTrack.SUCCESS)throw new IllegalStateException("AudioTrack setup failed");track.play();}catch(Exception e){stopSelf();}return START_NOT_STICKY;}
 int beat(){return track==null||beatSamples<=0?0:(track.getPlaybackHeadPosition()/beatSamples)%beats;}
 private void release(){if(track!=null){try{track.stop();}catch(IllegalStateException ignored){}track.release();track=null;}}
 public void onAudioFocusChange(int focus){if(focus<0)stopSelf();}
 public void onDestroy(){release();audio.abandonAudioFocus(this);stopForeground(true);instance=null;super.onDestroy();}
}
